'use strict';
const $ = (s) => document.querySelector(s);
const icon = (name) => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (s) => {try {const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:''} catch {return ''}};
let saved;
try {saved=new Set(JSON.parse(localStorage.getItem('sun-saved')||'[]'))}catch{saved=new Set()}
const state={merchants:[],category:'all',query:'',city:'',savedOnly:false,selected:null,user:null,sort:'featured',route:null,routeId:0,trailDismissed:false};
let map,clusters,tiles,routeLayer,userMarker,toastTimer,markers=new Map();
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function group(m){const c=m.category;if(/Coffee/.test(c))return 'coffee';if(/Restaurants|Bakeries|Bars|Groceries/.test(c))return 'food';if(/Shopping|Pets|Tech/.test(c))return 'shops';return 'other'}
function categoryIcon(m){const g=group(m);return g==='coffee'?'coffee':g==='food'?'food':g==='shops'?'shop':'spark'}
function shortCategory(m){return m.category.replace('Coffee Shops & Cafés','Coffee & cafés').replace('Restaurants & Quick Bites','Food & drink')}
function distance(a,b){const rad=Math.PI/180;const dlat=(b.lat-a.lat)*rad,dlon=(b.lon-a.lon)*rad;const x=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2;return 3958.8*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function featured(m){return ({'Echo Coffee':0,'Pita Cafe':1,'Scottsdale Burger Bar':2,'Stemistry':3,'The Buzzed Goat':4})[m.name]??10}
function filtered(){return state.merchants.filter(m=>(state.category==='all'||group(m)===state.category)&&(!state.city||m.city===state.city)&&(!state.savedOnly||saved.has(m.id))&&(!state.query||`${m.name} ${m.city} ${m.address} ${m.category}`.toLowerCase().includes(state.query))).sort((a,b)=>state.sort==='distance'&&state.user?distance(state.user,a)-distance(state.user,b):state.sort==='name'?a.name.localeCompare(b.name):featured(a)-featured(b)||a.name.localeCompare(b.name))}
function badge(m){return `<span class="bitcoin-badge">${m.lightning?icon('zap'):'<b style="color:var(--orange-dark)">₿</b>'}${m.lightning?'Lightning':'Bitcoin'}</span>`}
function render(){const rows=filtered();$('#result-count').textContent=`${rows.length} ${state.savedOnly?'saved ':''}place${rows.length===1?'':'s'} to explore`;$('#saved-count').textContent=saved.size;$('#map-count').textContent=`${rows.filter(m=>m.lat!==null).length} places`;$('#saved-nav').classList.toggle('active',state.savedOnly);$('#explore-nav').classList.toggle('active',!state.savedOnly);
$('#business-list').innerHTML=rows.length?rows.map(m=>`<article class="business-card ${state.selected===m.id?'selected':''}" data-id="${m.id}" tabindex="0" role="button" aria-label="View ${esc(m.name)}"><div class="card-art">${icon(categoryIcon(m))}</div><div class="card-content">${featured(m)<3?'<div class="card-eyebrow">Featured in Bitcoin Magazine</div>':''}<h3>${esc(m.name)}</h3><p class="card-address">${esc(m.address||m.city||'See map for location')}</p><div class="card-tags">${badge(m)}<span>${esc(shortCategory(m))}</span>${state.user&&m.lat?`<span>· ${distance(state.user,m).toFixed(1)} mi</span>`:''}</div></div><button class="save-button ${saved.has(m.id)?'saved':''}" data-save="${m.id}" aria-label="${saved.has(m.id)?'Unsave':'Save'} ${esc(m.name)}" aria-pressed="${saved.has(m.id)}">${icon('heart')}</button></article>`).join(''):`<div class="empty">${icon(state.savedOnly?'heart':'search')}<strong>${state.savedOnly?'Your next adventure starts here.':'No places found.'}</strong><br>${state.savedOnly?'Tap a heart on any business to save it here.':'Try another city, category, or search.'}<br><button id="reset-filters">Explore all places →</button></div>`;
if(clusters){clusters.clearLayers();markers.clear();rows.filter(m=>m.lat!==null).forEach(m=>{const marker=L.marker([m.lat,m.lon],{icon:L.divIcon({className:'map-marker-shell',html:`<div class="bitcoin-marker ${state.selected===m.id?'selected':''}" style="width:30px;height:30px"><span>₿</span></div>`,iconSize:[30,30],iconAnchor:[15,27]}),title:m.name,alt:m.name,keyboard:true});marker.bindTooltip(esc(m.name),{direction:'top',offset:[0,-25]});marker.on('click',()=>selectPlace(m.id));clusters.addLayer(marker);markers.set(m.id,marker)})}}
function fitResults(){const rows=filtered().filter(m=>m.lat!==null);if(rows.length)map.fitBounds(L.latLngBounds(rows.map(m=>[m.lat,m.lon])),{padding:[70,80],maxZoom:14});else notify('No places match these filters.')}
function updateFilters(fit=true){render();if(fit)fitResults()}
function savePlace(id){saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('sun-saved',JSON.stringify([...saved]))}catch{notify('Browser storage is unavailable. Saved for this visit.')}render();if(state.selected===id)renderDetail(state.merchants.find(m=>m.id===id))}
function mapsUrl(stops,origin){const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('travelmode','driving');const last=stops.at(-1);u.searchParams.set('destination',last.address||`${last.lat},${last.lon}`);if(origin)u.searchParams.set('origin',origin.address||`${origin.lat},${origin.lon}`);if(stops.length>1){const points=origin?stops.slice(0,-1):stops.slice(1,-1);if(!origin)u.searchParams.set('origin',stops[0].address||`${stops[0].lat},${stops[0].lon}`);if(points.length)u.searchParams.set('waypoints',points.map(m=>m.address||`${m.lat},${m.lon}`).join('|'))}return u.href}
function clearRoute(){state.routeId++;if(routeLayer){map.removeLayer(routeLayer);routeLayer=null}state.route=null}
function renderDetail(m){if(!m)return;$('#detail-panel').hidden=false;$('#trail-card').hidden=true;$('#detail-panel').innerHTML=`<button class="dismiss" data-action="close" aria-label="Close business details">×</button><span class="detail-category">${esc(shortCategory(m))}</span><h2>${esc(m.name)}</h2>${badge(m)}<p>${esc(m.address||'Address not listed in the article. Location from BTC Map.')}</p><div class="detail-links">${safeUrl(m.website)?`<a href="${esc(safeUrl(m.website))}" target="_blank" rel="noopener">Website ${icon('external')}</a>`:''}${m.phone?`<a href="tel:${esc(m.phone.replace(/[^+\d]/g,''))}">Call ${icon('arrow')}</a>`:''}${m.osmId?`<a href="https://btcmap.org/merchant/${esc(m.osmId)}" target="_blank" rel="noopener">BTC Map ${icon('external')}</a>`:''}</div><p class="route-status" id="route-status" hidden></p><button class="primary-button" data-action="directions">${icon('route')}Preview route from my location</button><a class="secondary-button" href="${esc(mapsUrl([m],state.user))}" target="_blank" rel="noopener">Open directions in Google Maps ${icon('external')}</a><button class="secondary-button" data-action="save">${icon('heart')}${saved.has(m.id)?'Saved to your places':'Save for a sunny day'}</button><button class="secondary-button" data-action="share">Share this place ${icon('arrow')}</button><a class="detail-report" data-community="correction" data-listing-id="${esc(m.id)}" href="${esc(BitcoinCommunity.issueUrl('correction',m))}" target="_blank" rel="noopener">Report incorrect listing ${icon('external')}</a><p class="report-note">Send a correction for review. No account needed.</p><p class="footnote">Listed in Bitcoin Magazine · Oct 19, 2026.<br>Confirm bitcoin payment with the business before visiting.</p>`}
function selectPlace(id,move=true){const m=state.merchants.find(m=>m.id===id);if(!m)return;clearRoute();state.selected=id;history.replaceState(null,'',`#${id}`);render();renderDetail(m);if(move&&m.lat!==null){map.flyTo([m.lat,m.lon],Math.max(14,map.getZoom()),{duration:.8})}if(innerWidth<=760)showMobileMap(true)}
function closeDetail(){clearRoute();state.selected=null;history.replaceState(null,'',location.pathname+location.search);$('#detail-panel').hidden=true;$('#trail-card').hidden=state.trailDismissed;render()}
async function locate(){if(state.user)return state.user;if(!navigator.geolocation)throw new Error('Your browser does not support location. Open directions in Google Maps instead.');return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(pos=>{state.user={lat:pos.coords.latitude,lon:pos.coords.longitude};if(userMarker)map.removeLayer(userMarker);userMarker=L.marker([state.user.lat,state.user.lon],{icon:L.divIcon({className:'user-marker',iconSize:[18,18]})}).addTo(map).bindTooltip('You are here');resolve(state.user)},()=>reject(new Error('Location unavailable. Enable location access, or use Google Maps directions.')),{enableHighAccuracy:false,timeout:12000,maximumAge:300000}))}
async function drawRoute(stops,statusEl){clearRoute();const requestId=state.routeId;statusEl.hidden=false;statusEl.textContent='Finding your orange route…';try{const coordinates=stops.map(m=>`${m.lon},${m.lat}`).join(';');const response=await fetch(`https://router.project-osrm.org/route/v1/driving/${coordinates}?overview=full&geometries=geojson`,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error();const data=await response.json();if(data.code!=='Ok'||!data.routes?.[0])throw Error();if(requestId!==state.routeId)return;const r=data.routes[0];routeLayer=L.geoJSON(r.geometry,{style:{color:'#f7931a',weight:5,opacity:1,className:'route-line'}}).addTo(map);state.route=r;map.fitBounds(routeLayer.getBounds(),{paddingTopLeft:[innerWidth>760?370:40,85],paddingBottomRight:[70,innerWidth<=760?240:70],maxZoom:15});statusEl.textContent=`${(r.distance/1609.344).toFixed(1)} miles · about ${Math.max(1,Math.round(r.duration/60))} min driving · no live traffic`}
catch{if(requestId!==state.routeId)return;statusEl.textContent='Road preview is unavailable. Open Google Maps below to get directions.'}}
function showMobileMap(show){$('.explorer').classList.toggle('map-view',show);$('#mobile-toggle').innerHTML=icon(show?'shop':'pin')+(show?'Show places':'Show map');if(map)setTimeout(()=>map.invalidateSize(),50)}
function setTheme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').innerHTML=icon(dark?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);$('meta[name="theme-color"]').content=dark?'#151a17':'#f7f7f2';if(map){if(tiles)map.removeLayer(tiles);let loaded=0,errors=0;tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);tiles.on('tileload',()=>{loaded++;$('#tile-notice').hidden=true});tiles.on('tileerror',()=>{errors++;if(!loaded&&errors>3)$('#tile-notice').hidden=false})}}
async function start(){setTheme();try{const res=await fetch('merchants.json');if(!res.ok)throw Error();const data=await res.json();state.merchants=data.merchants;BitcoinCommunity.setMerchants(state.merchants);$('#total-count').textContent=state.merchants.length;const cities=[...new Set(state.merchants.map(m=>m.city).filter(Boolean))].sort();$('#city').innerHTML='<option value="">All of Arizona</option>'+cities.map(c=>`<option>${esc(c)}</option>`).join('');if(!window.L)throw Error('Map library could not load.');map=L.map('map',{zoomControl:false,scrollWheelZoom:true,preferCanvas:true,maxZoom:19,minZoom:3}).setView([33.56,-112.03],10);clusters=L.markerClusterGroup({showCoverageOnHover:false,spiderfyOnMaxZoom:true,maxClusterRadius:38,iconCreateFunction:c=>L.divIcon({html:`${c.getChildCount()}`,className:'cluster-icon',iconSize:[37,37]})}).addTo(map);setTheme();render();if(location.hash.startsWith('#az-'))selectPlace(location.hash.slice(1));}catch(error){$('#result-count').textContent='Unable to load the map';$('#business-list').innerHTML=`<div class="empty">We couldn’t load the directory. Check your connection and refresh.<br><button id="reload">Try again →</button></div>`;console.error(error)}}
$('#theme-toggle').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('sun-theme',document.documentElement.dataset.theme)}catch{}setTheme()};
$('#search').oninput=e=>{state.query=e.target.value.trim().toLowerCase();updateFilters()};
$('#city').onchange=e=>{state.city=e.target.value;updateFilters()};
$('.category-filters').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;state.category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el===b));updateFilters()};
$('#sort').onchange=async e=>{state.sort=e.target.value;if(state.sort==='distance'&&!state.user){try{await locate()}catch(err){notify(err.message);state.sort='featured';e.target.value='featured'}}render()};
$('#business-list').onclick=e=>{const save=e.target.closest('[data-save]');if(save){savePlace(save.dataset.save);return}if(e.target.closest('#reset-filters')){reset();return}if(e.target.closest('#reload')){location.reload();return}const card=e.target.closest('[data-id]');if(card)selectPlace(card.dataset.id)};
$('#business-list').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-id]')){e.preventDefault();selectPlace(e.target.dataset.id)}};
function reset(){state.savedOnly=false;state.query='';state.city='';state.category='all';$('#search').value='';$('#city').value='';document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el.dataset.category==='all'));updateFilters()}
$('#saved-nav').onclick=()=>{state.savedOnly=true;closeDetail();render();fitResults();showMobileMap(false)};$('#explore-nav').onclick=()=>{state.savedOnly=false;render();showMobileMap(false)};
$('#story-nav').onclick=()=>$('#story-dialog').showModal();$('.dialog-close').onclick=()=>$('#story-dialog').close();$('#story-dialog').onclick=e=>{if(e.target===$('#story-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
$('#near-me').onclick=async()=>{const b=$('#near-me');b.disabled=true;notify('Finding nearby places…');try{await locate();state.sort='distance';$('#sort').value='distance';render();const nearest=filtered().filter(m=>m.lat!==null).slice(0,8);if(nearest.length)map.fitBounds(L.latLngBounds([state.user,...nearest].map(m=>[m.lat,m.lon])),{padding:[70,70],maxZoom:14});notify('Places sorted by distance from you.')}catch(e){notify(e.message)}finally{b.disabled=false}};
$('#zoom-in').onclick=()=>map?.zoomIn();$('#zoom-out').onclick=()=>map?.zoomOut();$('#fit-map').onclick=()=>fitResults();
$('#surprise').onclick=()=>{const rows=filtered();if(!rows.length){notify('Choose a broader filter to find your next stop.');return}selectPlace(rows[Math.floor(Math.random()*rows.length)].id);notify('A little serendipity, on the bitcoin standard.')};
$('#dismiss-trail').onclick=()=>{state.trailDismissed=true;$('#trail-card').hidden=true};
$('#trail-button').onclick=async()=>{state.selected=null;clearRoute();render();const stops=['Echo Coffee','Pita Cafe','Scottsdale Burger Bar'].map(name=>state.merchants.find(m=>m.name===name));$('#trail-card').hidden=true;$('#detail-panel').hidden=false;$('#detail-panel').innerHTML=`<button class="dismiss" data-action="close" aria-label="Close trail">×</button><div class="detail-category">THE SCOTTSDALE SATS TRAIL</div><h2>Follow the orange route.</h2><p>Start with a coffee, head north for a fresh pita, and stop by the burger bar next door.</p>${stops.map((m,i)=>`<div class="route-stop"><span>${i+1}</span>${esc(m.name)}</div>`).join('')}<p class="route-status" id="route-status"></p><a class="primary-button" href="${esc(mapsUrl(stops))}" target="_blank" rel="noopener">${icon('route')}Navigate this trail ${icon('external')}</a><p class="footnote">Pita Cafe and Scottsdale Burger Bar share an address. Drive times exclude stops and traffic.</p>`;if(innerWidth<=760)showMobileMap(true);await drawRoute(stops,$('#route-status'))};
$('#detail-panel').onclick=async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='close'){closeDetail();return}const m=state.merchants.find(m=>m.id===state.selected);if(!m)return;if(action==='save')savePlace(m.id);if(action==='share'){const url=new URL(location.href);url.hash=m.id;try{await navigator.clipboard.writeText(url.href);notify('Place link copied. Share a little sunshine.')}catch{notify('Copy the address in your browser to share this place.')}}if(action==='directions'){const button=e.target.closest('button');button.disabled=true;const status=$('#route-status');status.hidden=false;status.textContent='Finding your location…';try{const user=await locate();if(state.selected!==m.id)return;await drawRoute([user,m],status)}catch(err){if(state.selected===m.id)status.textContent=err.message}finally{button.disabled=false}}};
$('#mobile-toggle').onclick=()=>showMobileMap(!$('.explorer').classList.contains('map-view'));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#story-dialog').open&&!$('#submission-dialog').open){e.preventDefault();showMobileMap(false);$('#search').focus()}if(e.key==='Escape'&&!$('#story-dialog').open&&!$('#submission-dialog').open)closeDetail()});
start();
